merger.connect(gainNode);  
    gainNode.connect(ctx.destination);
oscLeft.start();  
    oscRight.start();
oscLeftRef.current \= oscLeft;  
    oscRightRef.current \= oscRight;  
    setIsPlaying(true);  
  };
useEffect(() \=\> {  
    return () \=\> {  
      if (audioCtxRef.current && audioCtxRef.current.state \!== 'closed') {  
